159			t.Fatalf("未保存成功的被拒绝申请不得进入历史，out=%q", show)
160		}
161	}
162	
163	// TestCLISaveInvalidTextKeepsQueryableState 保存被拒后，原先能够查询的学生与
164	// 学分仍可正常查询；本次想写入的含非法文字内容不落盘。
165	func TestCLISaveInvalidTextKeepsQueryableState(t *testing.T) {
166		dir := t.TempDir()
167		file := filepath.Join(dir, "records.json")
168		for _, st := range [][]string{
169			{"student", "s1"},
170			{"course", "c1", "数学", "4"},
