220		basis := "  竞赛获奖\t\\uD800  "
221		if out, _, code := runCLI(t, file, "waiver", "s\x01t", "r1", "w1", basis); code != 0 ||
222			!strings.Contains(out, "有效") {
223			t.Fatalf("含空白与字面 \\uD800 的依据应正常生效为有效免修，code=%d out=%q", code, out)
224		}
225	
226		// 重新打开进程，原样查回。show 用 %q 呈现依据，会把制表符与反斜线转义，
227		// 因此期望值也按同样的 %q 规则构造。
