package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// 本文件从命令行入口回归“保存时不得悄悄改写文字”。命令行参数在本机上可以
// 携带非法 UTF-8 字节（Go 的字符串按字节保留，不做替换），这些字节会原样
// 进入待保存的编号、名称、学期、依据或原因。标准库序列化会把它们静默替换成
// U+FFFD 却提示成功，因此保存必须明确拒绝这种数据：
//   - 退出码沿用保存失败的 2，标准错误说明保存失败、点名目标文件，并指出
//     无法原样保存的文字所在的记录类别与具体字段；
//   - 标准输出不能出现登记成功、免修已生效、历史已保存或文件已创建等提示；
//   - 已有记录文件逐字节保留、原先能查询的学生与学分照常查询；目标文件原本
//     不存在时不得留下新记录文件或临时文件；
//   - 即使问题只在一条已拒绝免修的文字里，也拒绝整次保存，历史不落盘；
//   - 合法文字（用户确实输入的“�”、中文与补充平面字符、编号中合法的控制
//     字符、依据中的空白、字面上的“\uD800”）继续正常保存使用。

// invalidUTF8Arg 返回一个带非法 UTF-8 字节的参数。
func invalidUTF8Arg(prefix string) string { return prefix + string([]byte{0xFF}) }

// assertSaveRejectsBadText 在“保存失败”通用断言之外，额外要求错误指出无法
// 原样保存的文字、记录类别与具体字段。
func assertSaveRejectsBadText(t *testing.T, file string, args []string, category, field, label string) {
	t.Helper()
	out, errText, code := runCLI(t, file, args...)
	if code != exitFile {
		t.Fatalf("%s：应按保存失败退出码 %d 结束，code=%d out=%q err=%q",
			label, exitFile, code, out, errText)
	}
	if out != "" {
		t.Fatalf("%s：保存失败时标准输出必须为空，out=%q", label, out)
	}
	for _, want := range []string{"保存记录文件", file, "失败", "无法原样保存", category, field} {
		if !strings.Contains(errText, want) {
			t.Fatalf("%s：错误输出应包含 %q（说明保存失败、目标文件、类别 %q 与字段 %q），err=%q",
				label, want, category, field, errText)
		}
	}
}

// TestCLISaveRejectsInvalidUTF8NotCreated 目标文件原本不存在时，待保存文字
// 含非法 UTF-8（学生编号、课程名称、学期、免修依据等）必须拒绝整次保存：
// 退出码 2、标准输出为空，目标文件与临时文件都不得留下。
func TestCLISaveRejectsInvalidUTF8NotCreated(t *testing.T) {
	cases := []struct {
		label    string
		args     []string
		category string
		field    string
	}{
		{"学生编号非法", []string{"student", invalidUTF8Arg("s")}, "学生", "编号"},
		{"课程编号非法", []string{"course", invalidUTF8Arg("c"), "数学", "4"}, "课程", "编号"},
		{"课程名称非法", []string{"course", "c1", invalidUTF8Arg("数学"), "4"}, "课程", "名称"},
		{"学期非法", []string{"enroll", "s1", "r1", invalidUTF8Arg("2024春"), "e1"}, "修读", "学期"},
		{"免修依据非法", []string{"waiver", "s1", "r1", "w9", invalidUTF8Arg("依据")}, "免修", "依据"},
		{"撤销原因非法", []string{"revoke-waiver", "s1", "w1", invalidUTF8Arg("原因")}, "免修", "原因"},
	}
	for _, c := range cases {
		t.Run(c.label, func(t *testing.T) {
			dir := t.TempDir()
			file := filepath.Join(dir, "records.json")
			// enroll/waiver/revoke 需要前置记录；这些前置命令本身必须正常落盘。
			for _, st := range [][]string{
				{"student", "s1"},
				{"course", "c1", "数学", "4"},
				{"req", "s1", "r1", "c1"},
				{"waiver", "s1", "r1", "w1", "原始依据"},
			} {
				if _, errText, code := runCLI(t, file, st...); code != 0 {
					t.Fatalf("前置步骤 %v 失败，code=%d err=%q", st, code, errText)
				}
			}
			before, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}

			assertSaveRejectsBadText(t, file, c.args, c.category, c.field, c.label)

			if _, statErr := os.Stat(file); statErr != nil {
				t.Fatalf("%s：前置已创建的记录文件应继续存在：%v", c.label, statErr)
			}
			after, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			if string(before) != string(after) {
				t.Fatalf("%s：拒绝保存后原文件必须逐字节保留\nwant=%q\n got=%q",
					c.label, before, after)
			}
			leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
			if len(leftover) != 0 {
				t.Fatalf("%s：不得残留临时文件：%v", c.label, leftover)
			}
		})
	}
}

// TestCLISaveRejectsInvalidUTF8ForBrandNewFile 目标文件与前置数据都不存在时，
// 第一条登记命令的文字就非法：不得创建任何记录文件，也不能提示已登记或已
// 创建。
func TestCLISaveRejectsInvalidUTF8ForBrandNewFile(t *testing.T) {
	file := filepath.Join(t.TempDir(), "records.json")
	assertSaveRejectsBadText(t, file, []string{"student", invalidUTF8Arg("s")},
		"学生", "编号", "全新文件登记非法编号学生")

	if _, err := os.Stat(file); !os.IsNotExist(err) {
		t.Fatalf("目标文件原本不存在时不得留下新记录文件，stat err=%v", err)
	}
}

// TestCLISaveRejectedWaiverBadTextRefusesWholeSave 因目标要求不存在而本应被
// 拒绝、但要写入免修历史的首次申请，其依据含非法 UTF-8 时也必须拒绝整次
// 保存：不能只跳过历史、不能显示“已拒绝/已记入历史”，退出码 2，恢复后
// 历史中查不到该申请。
func TestCLISaveRejectedWaiverBadTextRefusesWholeSave(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "records.json")
	if _, _, code := runCLI(t, file, "student", "s1"); code != 0 {
		t.Fatal("前置登记学生失败")
	}
	before, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}

	out, errText, code := runCLI(t, file, "waiver", "s1", "rX", "wbad", invalidUTF8Arg("依据"))
	if code != exitFile {
		t.Fatalf("含非法文字的被拒绝免修应拒绝整次保存、退出码 %d，code=%d out=%q err=%q",
			exitFile, code, out, errText)
	}
	if out != "" || strings.Contains(out, "已拒绝") || strings.Contains(out, "免修历史") {
		t.Fatalf("保存失败时不得宣布申请已拒绝或历史已保存，out=%q", out)
	}
	if !strings.Contains(errText, "免修") || !strings.Contains(errText, "依据") {
		t.Fatalf("错误应指出免修依据无法原样保存，err=%q", errText)
	}

	after, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	if string(before) != string(after) {
		t.Fatal("拒绝保存后原文件必须逐字节保留")
	}

	// 重新打开进程：未保存成功的申请不在历史中，原有学生仍可查询。
	show, _, code := runCLI(t, file, "show", "s1")
	if code != 0 {
		t.Fatalf("原文件应仍可正常查询，code=%d out=%q", code, show)
	}
	if strings.Contains(show, "wbad") {
		t.Fatalf("未保存成功的被拒绝申请不得进入历史，out=%q", show)
	}
}

// TestCLISaveInvalidTextKeepsQueryableState 保存被拒后，原先能够查询的学生与
// 学分仍可正常查询；本次想写入的含非法文字内容不落盘。
func TestCLISaveInvalidTextKeepsQueryableState(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "records.json")
	for _, st := range [][]string{
		{"student", "s1"},
		{"course", "c1", "数学", "4"},
		{"req", "s1", "r1", "c1"},
		{"waiver", "s1", "r1", "w1", "竞赛获奖"},
	} {
		if _, errText, code := runCLI(t, file, st...); code != 0 {
			t.Fatalf("前置步骤 %v 失败：%q", st, errText)
		}
	}

	// 试图登记名称含非法字节的第二门课程：保存失败。
	assertSaveRejectsBadText(t, file,
		[]string{"course", "c2", invalidUTF8Arg("物理"), "3"}, "课程", "名称", "追加非法课程")

	check, _, code := runCLI(t, file, "check", "s1")
	if code != 0 || !strings.Contains(check, "总学分：4") ||
		!strings.Contains(check, "来源为有效免修 w1") {
		t.Fatalf("保存被拒后原有学分与免修来源应照常可查，code=%d out=%q", code, check)
	}
	list, _, code := runCLI(t, file, "list-courses")
	if code != 0 || !strings.Contains(list, "数学") || strings.Contains(list, "物理") {
		t.Fatalf("新课程不应落盘、旧课程应仍在，code=%d out=%q", code, list)
	}
}

// TestCLISaveAcceptsLegalUnicodeText 合法文字继续按既有规则保存与使用：
// 用户确实输入的“�”、中文与补充平面字符、编号中合法的控制字符、依据中的
// 空白、命令行字面上的“\uD800”都不能误拒绝，保存后可原样查回。
func TestCLISaveAcceptsLegalUnicodeText(t *testing.T) {
	file := filepath.Join(t.TempDir(), "records.json")

	// 编号中合法的控制字符 U+0001，以及用户确实输入的“�”。
	if out, _, code := runCLI(t, file, "student", "s\x01t"); code != 0 ||
		!strings.Contains(out, "已登记学生") {
		t.Fatalf("含合法控制字符的学生编号应正常登记，code=%d out=%q", code, out)
	}
	if _, _, code := runCLI(t, file, "student", "s�2"); code != 0 {
		t.Fatal("用户确实输入的“�”是合法文字，应正常登记")
	}
	// 中文与补充平面字符课程名称。
	if _, _, code := runCLI(t, file, "course", "c1", "高等数学😀", "4"); code != 0 {
		t.Fatal("含补充平面字符的课程名称应正常登记")
	}
	if _, _, code := runCLI(t, file, "req", "s\x01t", "r1", "c1"); code != 0 {
		t.Fatal("含控制字符编号的学生名下登记要求应正常")
	}
	// 学期含补充平面字符。
	if _, _, code := runCLI(t, file, "enroll", "s\x01t", "r1", "2024😀春", "e1"); code != 0 {
		t.Fatal("含补充平面字符的学期应正常登记")
	}
	// 依据含前后空白与字面上的“\uD800”（反斜线 + 普通字母数字）。
	basis := "  竞赛获奖\t\\uD800  "
	if out, _, code := runCLI(t, file, "waiver", "s\x01t", "r1", "w1", basis); code != 0 ||
		!strings.Contains(out, "有效") {
		t.Fatalf("含空白与字面 \\uD800 的依据应正常生效为有效免修，code=%d out=%q", code, out)
	}

	// 重新打开进程，原样查回。show 用 %q 呈现依据，会把制表符与反斜线转义，
	// 因此期望值也按同样的 %q 规则构造。
	out, _, code := runCLI(t, file, "show", "s\x01t")
	if code != 0 {
		t.Fatalf("含控制字符编号应可查询，code=%d out=%q", code, out)
	}
	if !strings.Contains(out, "学生 s\x01t") ||
		!strings.Contains(out, "学期 2024😀春") ||
		!strings.Contains(out, "依据 "+fmt.Sprintf("%q", basis)) {
		t.Fatalf("合法文字应原样保存查回，out=%q", out)
	}
	check, _, code := runCLI(t, file, "check", "s\x01t")
	if code != 0 || !strings.Contains(check, "总学分：4") ||
		!strings.Contains(check, "有效免修 w1") {
		t.Fatalf("正常保存后学分来源与免修历史不应改变，code=%d out=%q", code, check)
	}
}

package credit

import (
	"encoding/json"
	"fmt"
	"io"
	"reflect"
	"strings"
	"unicode/utf8"
)

// duplicateFieldError 表示同一个 JSON 对象内出现了读取功能无法确定归属的
// 两个字段：
//   - 字段名完全相同（first == second，如两份 "credit"）；
//   - 两个字段名只有大小写差异（编码/json 的大小写折叠等同于
//     strings.EqualFold），却都被现有读取功能识别为同一条记录字段
//     （如 "credit" 与 "Credit" 都填入课程学分，"courses" 与
//     "COURSES" 都填入最外层课程列表）。
//
// field 是两者共同指向的规范字段名（结构体 json 标签原文）；完全同名时
// 与 first、second 相同。
type duplicateFieldError struct {
	field  string
	first  string
	second string
}

func (e *duplicateFieldError) Error() string {
	if e.first == e.second {
		return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.first)
	}
	return fmt.Sprintf(
		"同一 JSON 对象内字段名 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定",
		e.first, e.second, e.field)
}

// nullCourseOpenError 表示某条课程记录显式提供了开放状态字段，却把值写成
// JSON 的 null（"open":null，大小写与 Unicode 转义变体同理）。课程编号、
// 名称与学分合法也不能放过：标准库把 null 解进非指针 bool 时不报错、字段
// 保持零值 false，于是“状态未确定”的记录被悄悄读成“停开”，课程列表显示
// 停开、新增修读被误拒，之后任何一次保存还会把未定状态写成明确的 false。
// 这属于记录内容损坏，必须拒绝整份文件，而不是跳过该课程继续办理。
//
// courseID 是该课程对象内 id 字段解码后的编号（字段位置不影响判定，编号
// 出现在开放状态之后也能取到；课程确实没有编号时为空串）；key 是开放状态
// 字段的原始写法（解码后文字），用于说明是哪一种写法被写成了 null。
type nullCourseOpenError struct {
	courseID string
	key      string
}

func (e *nullCourseOpenError) Error() string {
	id := e.courseID
	if id == "" {
		id = "（该课程记录未提供编号）"
	}
	return fmt.Sprintf(
		"课程 %s 的课程开放状态为空：字段 %q 被显式写成 null，开放状态只能是 true（开放）或 false（停开）",
		id, e.key)
}

// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
// “能被现有读取功能识别”的字段名。
type objKind int

const (
	objUnknown     objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
	objFile                       // 记录最外层 fileData
	objCourse                     // courses 数组元素：课程
	objStudent                    // students 数组元素：学生
	objRequirement                // requirements 数组元素：课程要求
	objEnrollment                 // enrollments 数组元素：修读
	objWaiver                     // waivers 数组元素：免修
)

// recordObjectTypes 把每类对象对应到它在记录格式中的结构体类型。各类对象
// “能被读取功能识别哪些字段名”只有结构体定义上的 json 标签这一个出处：
// 正常读取时 json.Decoder 按这些标签（先精确名、再大小写折叠名）填入字段，
// 字段重复扫描与课程开放状态扫描也从同一份结构体定义取字段名。调整一项
// 记录的字段（增删、改名、换标签）只需改结构体定义，正常读取与两项扫描
// 始终对“哪些字段可识别、哪些写法指向同一字段、键下是不是课程对象”作出
// 一致判断，不需要再同步另一份字段名称清单。
var recordObjectTypes = map[objKind]reflect.Type{
	objFile:        reflect.TypeOf(fileData{}),
	objCourse:      reflect.TypeOf(Course{}),
	objStudent:     reflect.TypeOf(Student{}),
	objRequirement: reflect.TypeOf(Requirement{}),
	objEnrollment:  reflect.TypeOf(Enrollment{}),
	objWaiver:      reflect.TypeOf(Waiver{}),
}

// jsonFieldName 按 encoding/json 的规则给出结构体字段被识别的 JSON 名称：
// 未导出字段不参与解码；json 标签为 "-" 的字段跳过（返回空串）；没有标签
// 时用 Go 字段名本身；omitempty 等选项不影响名称。记录结构体均为扁平字段，
// 无嵌入字段提升问题。
func jsonFieldName(sf reflect.StructField) string {
	if sf.PkgPath != "" {
		return ""
	}
	name := sf.Tag.Get("json")
	if name == "-" {
		return ""
	}
	if comma := strings.IndexByte(name, ','); comma >= 0 {
		name = name[:comma]
	}
	if name == "" {
		name = sf.Name
	}
	return name
}

// recordFields 是各类对象能被读取功能识别的字段名（结构体 json 标签原文），
// 全部直接取自 recordObjectTypes 中的结构体定义，不在别处另列一份。
// 同一对象的字段名在大小写不敏感比较下必须两两不同——否则该格式本身就有
// 歧义（两个字段折叠到同一名称），在初始化阶段直接指出这类定义错误。
var recordFields = buildRecordFields()

func buildRecordFields() map[objKind][]string {
	m := make(map[objKind][]string, len(recordObjectTypes))
	for kind, t := range recordObjectTypes {
		names := make([]string, 0, t.NumField())
		for i := 0; i < t.NumField(); i++ {
			name := jsonFieldName(t.Field(i))
			if name == "" {
				continue
			}
			for _, other := range names {
				if strings.EqualFold(name, other) {
					panic(fmt.Sprintf(
						"记录结构体 %s 的字段 %q 与 %q 在大小写折叠后同名，记录格式存在歧义",
						t.Name(), name, other))
				}
			}
			names = append(names, name)
		}
		m[kind] = names
	}
	return m
}

// matchRecordField 报告键名 key 是否会被现有读取功能填入 kind 对象的某个
// 记录字段，命中时返回该字段的规范名称（json 标签原文）。
//
// encoding/json 解进结构体时先按精确名匹配，不中再按大小写折叠名匹配，
// 折叠规则等同于 strings.EqualFold（完整 Unicode 简单折叠，而非仅 ASCII：
// 例如 U+212A“K”折到 k、U+0130“İ”折到 i）。这里照搬同一判定，字段名又
// 直接来自结构体标签，才能保证“两个键名被现有读取功能识别为同一字段”的
// 口径与实际解码完全一致——任何大小写或 Unicode 转义组合都无法让一个键
// 绕过本扫描却仍被解码器接受。字段归属唯一性检查与课程开放状态检查都经
// 由这同一个入口识别字段，两者口径始终相同。
func matchRecordField(kind objKind, key string) (string, bool) {
	for _, tag := range recordFields[kind] {
		if strings.EqualFold(key, tag) {
			return tag, true
		}
	}
	return "", false
}

// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
// 记录格式里只有最外层的五个数组承载记录对象。归属同样直接由 fileData 的
// 结构体定义推导：键按大小写折叠命中哪个字段，就取该字段（切片取元素、
// 指针解引用）的类型再反查对象类型——courses 与 COURSES 解出来都是课程
// 列表，其元素必须按课程对象检查，不能借顶层键的大小写写法绕过限制；
// version 等非记录对象字段返回 objUnknown。
func fileKeyObjectKind(key string) objKind {
	t := recordObjectTypes[objFile]
	for i := 0; i < t.NumField(); i++ {
		sf := t.Field(i)
		name := jsonFieldName(sf)
		if name == "" || !strings.EqualFold(name, key) {
			continue
		}
		ft := sf.Type
		if ft.Kind() == reflect.Slice {
			ft = ft.Elem()
		}
		if ft.Kind() == reflect.Ptr {
			ft = ft.Elem()
		}
		for kind, rt := range recordObjectTypes {
			if rt == ft {
				return kind
			}
		}
		return objUnknown
	}
	return objUnknown
}

// recordTokenHooks 是 walkFirstRecordValue 向具体检查开放的时机。
// 字段归属检查与课程开放状态检查只提供各自的“发现规则”，不再各自处理
// 对象与数组的层次、记录类别推导，以及键与字符串值的区分——这些共通规则
// 全部集中在遍历器一处维护。
//
// 回调拿到的 kind/key 都由遍历器按记录结构推导：
//   - objectStart 在每个对象（含根对象）压栈后调用一次，kind 是该对象在
//     记录格式中的类别（objUnknown 表示不属于记录格式的对象）；
//   - key 在对象内读到键时调用，key 是 JSON 解码后的键名原文（\uXXXX
//     转义已还原），与正常解码时看到的写法不可区分；
//   - stringValue 在读到字符串“值”（不是键）时调用，key 是其所属键的
//     原文，value 是解码后的文字；
//   - scalarValue 在读到其余标量值（number、bool、null）时调用，key 是
//     其所属键的原文；tok 为无类型 nil 时即 JSON null——字符串字面量
//     "null" 走 stringValue，绝不会以 nil 出现，名称、依据里的“null”
//     文字因此天然不被当成空值；
//   - objectEnd 在对象的 '}' 读到、结构帧出栈之前调用，便于检查汇总整个
//     对象（如课程编号出现在问题字段之后，仍能在对象闭合时点名课程）。
//
// 数组本身不产生回调；数组各元素对象照常成对触发 objectStart/objectEnd。
// 任一带返回值的回调返回非 nil 错误时，遍历立即中止并原样返回该错误。
type recordTokenHooks struct {
	objectStart func(kind objKind)
	key         func(kind objKind, key string) error
	stringValue func(kind objKind, key, value string) error
	scalarValue func(kind objKind, key string, tok any) error
	objectEnd   func(kind objKind) error
}

// walkFirstRecordValue 遍历第一份完整 JSON 值的 token 流：按记录结构维护
// 对象/数组栈，把“对象起止、键、标量值”四个时机交给 hooks。第一份值之后
// 的字节一律不读——调用方另行检查完整记录之后是否拼接了多余内容，那里的
// 报错信息必须与本遍历中的检查区分开。
//
// 对象类别与正常解码同一出处（见 fileKeyObjectKind）：根对象是最外层
// fileData；对象直接挂在最外层对象的某个键下时，类别由该键按大小写折叠
// 推导（courses 与 COURSES 之下都是课程对象）；对象在数组里时类别跟随
// 承载它的数组，数组嵌套则逐层沿用——顶层键的大小写写法与数组嵌套都不能
// 改变元素对象被识别成的记录类别，两项检查由此始终按同一口径识别课程
// 记录。
//
// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），遍历器据此
// 区分字符串 token 是键还是字符串值；嵌套对象/数组整体结束时也算外层键
// 对应的值读完。限制只针对同一对象：每个对象独立成帧，数组各元素、不同
// 课程或不同学生互不比较。
//
// 语法残缺（未闭合、值缺失等）不在本遍历的报错范围：returnSyntaxErr 为
// false 时一律按“未发现本检查的问题”返回 nil，语法问题留给调用方随后的
// 结构体解码阶段报告；为 true 时把 json.Decoder 的语法错误原样返回（调用
// 方同样只从中识别自己的检查错误，其余仍交给解码阶段）。io.EOF（含空
// 输入）两种模式下都返回 nil。
func walkFirstRecordValue(r io.Reader, returnSyntaxErr bool, hooks recordTokenHooks) error {
	type frame struct {
		isObj bool
		// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
		kind objKind
		// elem 标识数组元素对象的类型（数组帧使用）。
		elem objKind
		// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
		// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。对象内
		// token 天然按键、值、键、值交替（逗号不产生 token），借此区分
		// 字符串 token 是键还是普通字符串值。
		expectKey bool
		// pendingKey 是当前值所属的键（解码后文字），用于判断嵌套对象/
		// 数组的类型，并随标量值回调交给具体检查。
		pendingKey string
	}
	var stack []frame
	depth := 0

	push := func(d json.Delim) {
		switch d {
		case '{':
			kind := objUnknown
			if n := len(stack); n == 0 {
				// 第一份值的根对象即记录最外层；根值不是对象时结构体
				// 解码阶段自会按类型拒绝。
				kind = objFile
			} else if p := &stack[n-1]; p.isObj {
				if p.kind == objFile {
					kind = fileKeyObjectKind(p.pendingKey)
				}
			} else {
				// 对象在数组里：类型由承载它的数组决定（数组类型又由
				// 最外层五个字段之一决定）。
				kind = stack[n-1].elem
			}
			stack = append(stack, frame{isObj: true, kind: kind, expectKey: true})
			if hooks.objectStart != nil {
				hooks.objectStart(kind)
			}
		case '[':
			elem := objUnknown
			if n := len(stack); n > 0 {
				if p := &stack[n-1]; p.isObj {
					if p.kind == objFile {
						elem = fileKeyObjectKind(p.pendingKey)
					}
				} else {
					// 数组嵌套：内层数组元素类型跟随外层数组。
					elem = p.elem
				}
			}
			stack = append(stack, frame{isObj: false, elem: elem})
		}
	}
	// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
	valueEnded := func() {
		if n := len(stack); n > 0 {
			f := &stack[n-1]
			if f.isObj && !f.expectKey {
				f.expectKey = true
				f.pendingKey = ""
			}
		}
	}

	dec := json.NewDecoder(r)
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
			return nil
		}
		if err != nil {
			if returnSyntaxErr {
				return err
			}
			// 语法问题留给随后的结构体解码报告；本检查只负责自己的发现。
			return nil
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{', '[':
				depth++
				push(t)
			case '}', ']':
				depth--
				cur := stack[len(stack)-1]
				if t == '}' && hooks.objectEnd != nil {
					// 出栈前汇总：课程编号等对象内信息此刻无论先后都已
					// 到齐。
					if err := hooks.objectEnd(cur.kind); err != nil {
						return err
					}
				}
				stack = stack[:len(stack)-1]
				if depth == 0 {
					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
					return nil
				}
				// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
				valueEnded()
			}
		case string:
			n := len(stack)
			if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
				f := &stack[n-1]
				if hooks.key != nil {
					if err := hooks.key(f.kind, t); err != nil {
						return err
					}
				}
				f.expectKey = false
				f.pendingKey = t
				continue
			}
			// 字符串值：名称、依据等普通文字在这里出现，包括字面写出的
			// "null" 与字段名，都只是文字。
			if n > 0 && stack[n-1].isObj {
				f := &stack[n-1]
				if hooks.stringValue != nil {
					if err := hooks.stringValue(f.kind, f.pendingKey, t); err != nil {
						return err
					}
				}
				valueEnded()
			}
			if depth == 0 {
				return nil // 顶层标量值
			}
		default:
			// number、bool 等标量值；JSON null 的 token 是无类型 nil。
			if n := len(stack); n > 0 && stack[n-1].isObj {
				f := &stack[n-1]
				if hooks.scalarValue != nil {
					if err := hooks.scalarValue(f.kind, f.pendingKey, tok); err != nil {
						return err
					}
				}
				valueEnded()
			}
			if depth == 0 {
				return nil
			}
		}
	}
}

// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
//
// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
// 后一个静默覆盖，而且结构体字段按大小写折叠匹配 json 标签（规则等同于
// strings.EqualFold）——同一门课程同时写 "credit":4 与 "Credit":9 时，
// 标准库读不出“曾经写过两个”，学分直接被后一个值顶替，两个键先后颠倒
// 结果也随之颠倒。因此在正常结构体解码之前先单独扫描一遍 token 流。
//
// 检查只保留自己的发现规则，层次与类别推导全部复用 walkFirstRecordValue：
//   - 同一个 JSON 对象内字段归属只能确定一次：完全同名的两个键，或两个
//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
//     Credit、student 与 Student、courses 与 COURSES），发现即返回
//     *duplicateFieldError（含规范字段名与两个原始写法）。
//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
//     的两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
//     绕开限制。
//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
func scanDuplicateKeys(r io.Reader) error {
	type dupState struct {
		// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
		rawKeys map[string]struct{}
		// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
		// 字段名为索引；无法识别的键不进此表。
		seen map[string]string
	}
	// 每个对象一份状态，随遍历器的 objectStart/objectEnd 成对压退，天然
	// 只在同一对象内比较；数组不压状态，元素对象各自独立。
	var states []dupState

	hooks := recordTokenHooks{
		objectStart: func(objKind) {
			states = append(states, dupState{
				rawKeys: map[string]struct{}{},
				seen:    map[string]string{},
			})
		},
		objectEnd: func(objKind) error {
			states = states[:len(states)-1]
			return nil
		},
		key: func(kind objKind, key string) error {
			st := &states[len(states)-1]
			// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义形式的
			// 键名与直接写出的同名键在这里完全不可区分。
			if _, dup := st.rawKeys[key]; dup {
				return &duplicateFieldError{field: key, first: key, second: key}
			}
			st.rawKeys[key] = struct{}{}
			// 只有指向同一条可识别记录字段的不同写法才算归属冲突；
			// 未知键的大小写变体随后由结构体解码按未知字段拒绝（如
			// "foo" 与 "Foo" 不会被当成任何业务字段）。
			if canonical, known := matchRecordField(kind, key); known {
				if prev, conflict := st.seen[canonical]; conflict {
					return &duplicateFieldError{
						field:  canonical,
						first:  prev,
						second: key,
					}
				}
				st.seen[canonical] = key
			}
			return nil
		},
	}
	// 语法残缺由遍历器原样返回 json.Decoder 错误；Load 只按
	// *duplicateFieldError 识别本检查的发现，其余错误仍交给解码阶段。
	return walkFirstRecordValue(r, true, hooks)
}

// scanNullCourseOpen 扫描第一份完整 JSON 值的 token 流：只要某个课程对象
// （courses 数组元素，含最外层键的大小写变体与数组嵌套）显式给出开放状态
// 字段且值是 JSON null，就返回 *nullCourseOpenError。
//
// 与 scanDuplicateKeys 共用同一遍历与字段识别口径（见
// walkFirstRecordValue 与 matchRecordField），今后调整记录结构时两项检查
// 仍按同一口径识别课程记录：
//   - 键名以 JSON 解码后的文字按 strings.EqualFold 与课程结构体的 open
//     标签比较，open、Open、OPEN 以及解码后等同于这些写法的 \uXXXX 转义
//     都指向同一状态字段，字段在课程对象中的位置不影响结果；
//   - 只认“键后紧跟的值 token 就是 nil（JSON null）”这一种情形：字符串
//     字面量 "null" 走字符串值回调，是普通文字，课程名称、免修依据里出现
//     它不算状态空值；开放状态写成对象/数组等其他类型留给结构体解码按
//     类型错误拒绝。
//
// 课程对象之外的 null 不由本检查处理：最外层的 null 或空数组继续按既有
// 读取规则判读（顶层 null/数组本来就不是合法记录），"courses":null 这类
// 空列表照常按没有课程读取。报错推迟到该课程对象完整读完时（objectEnd）
// 发出，这样无论 id 字段出现在开放状态之前还是之后，错误都能点名课程
// 编号。
func scanNullCourseOpen(r io.Reader) error {
	type openState struct {
		// courseID 记录本课程对象已读到的编号，供报错时点名。
		courseID string
		// openNullKey 记录开放状态被写成 null 时该字段的原始写法；
		// 非空表示本课程对象已构成损坏。
		openNullKey string
	}
	// 每个对象一份状态，随遍历器的 objectStart/objectEnd 成对压退；只有
	// 课程对象会写入其中字段。
	var states []openState

	hooks := recordTokenHooks{
		objectStart: func(objKind) {
			states = append(states, openState{})
		},
		objectEnd: func(kind objKind) error {
			st := &states[len(states)-1]
			var err error
			if kind == objCourse && st.openNullKey != "" {
				// 课程对象已完整读完，id 无论先后都已记录在案。
				err = &nullCourseOpenError{courseID: st.courseID, key: st.openNullKey}
			}
			states = states[:len(states)-1]
			return err
		},
		stringValue: func(kind objKind, key, value string) error {
			// 字符串值：在课程对象内顺带记录编号；普通文字 "null" 走的
			// 也是这里，绝不会被当成开放状态空值。
			if kind == objCourse {
				if canonical, ok := matchRecordField(objCourse, key); ok && canonical == "id" {
					states[len(states)-1].courseID = value
				}
			}
			return nil
		},
		scalarValue: func(kind objKind, key string, tok any) error {
			if kind == objCourse && tok == nil {
				if canonical, ok := matchRecordField(objCourse, key); ok && canonical == "open" {
					st := &states[len(states)-1]
					// 只记第一处；整份文件都会被拒绝，列出哪一门都成立。
					if st.openNullKey == "" {
						st.openNullKey = key
					}
				}
			}
			return nil
		},
	}
	// 语法问题留给随后的结构体解码报告；本检查只负责发现 null 状态。
	return walkFirstRecordValue(r, false, hooks)
}

// rejectReasonProblem 说明已拒绝免修的拒绝原因是以哪种方式缺失的。
type rejectReasonProblem int

const (
	// reasonAbsent：免修对象里根本没有 reason 字段。
	reasonAbsent rejectReasonProblem = iota
	// reasonNull：reason 字段被显式写成 JSON null。
	reasonNull
	// reasonBlank：reason 是空字符串或只含空白字符的字符串。
	reasonBlank
	// reasonWrongType：reason 的值不是字符串（number、bool、对象或数组）。
	reasonWrongType
)

// missingRejectReasonError 表示某条状态为 rejected 的免修申请没有保留含
// 实际文字的拒绝原因。被拒绝的申请必须能说明当时为什么没有生效：缺了原因，
// check 列出的申请就无从解释，随后登记其他记录还可能把这份不完整历史继续
// 保存下去。因此这属于记录内容损坏，必须拒绝整份文件，而不是把它当成没有
// 原因的正常历史继续核对或保存——哪怕这条申请不属于本次查询的学生，或其
// 目标要求已另有通过修读、有效免修、照常能算出学分。
//
// studentID/waiverID 分别是该免修对象内 student、id 字段解码后的文字
// （字段位置不影响判定，编号出现在原因之后也能取到；对象确实没有该字段时
// 为空串）；key 是原因字段的原始写法（解码后文字），reasonAbsent 时为空。
type missingRejectReasonError struct {
	studentID string
	waiverID  string
	key       string
	problem   rejectReasonProblem
}

func (e *missingRejectReasonError) Error() string {
	student := e.studentID
	if student == "" {
		student = "（该免修记录未提供学生编号）"
	}
	waiver := e.waiverID
	if waiver == "" {
		waiver = "（该免修记录未提供免修编号）"
	}
	head := fmt.Sprintf("学生 %s 的已拒绝免修 %s 缺少拒绝原因", student, waiver)
	switch e.problem {
	case reasonNull:
		return fmt.Sprintf(
			"%s：字段 %q 被显式写成 null，已拒绝申请必须保留含实际文字的拒绝原因",
			head, e.key)
	case reasonBlank:
		return head + "：原因为空字符串或只含空白字符，已拒绝申请必须保留含实际文字的拒绝原因"
	case reasonWrongType:
		return fmt.Sprintf(
			"%s：原因字段 %q 不是文字，已拒绝申请的拒绝原因必须是含实际文字的字符串",
			head, e.key)
	default:
		return head + "：记录中没有原因字段，已拒绝申请必须保留含实际文字的拒绝原因"
	}
}

// scanRejectedWaiverReasons 扫描第一份完整 JSON 值的 token 流：只要某个
// 免修对象（waivers 数组元素，含最外层键的大小写变体与数组嵌套）的状态
// 确为字符串 "rejected"，其 reason 就必须是含实际文字的字符串，否则返回
// *missingRejectReasonError。
//
// 必须在结构体解码之前单独扫描，因为仅看解码后的 Waiver.Reason（普通
// string）区分不了“字段没有出现”“"reason":null”与 "reason":""：标准库
// 把缺失字段与 JSON null 都解成零值空串，而这三种情形本次都要拒绝。
//
// 与 scanNullCourseOpen、scanDuplicateKeys 共用同一遍历与字段识别口径
// （见 walkFirstRecordValue 与 matchRecordField）：
//   - 键名以 JSON 解码后的文字按 strings.EqualFold 与免修结构体的标签
//     比较，reason、Reason、REASON 以及解码后等同的 \uXXXX 转义都指向
//     同一原因字段，student、id、status 同理，字段在对象中的位置不影响
//     结果，编号/学生出现在原因之后仍能在对象闭合时点名；
//   - “空白”按 strings.TrimSpace 的 Unicode 口径判定：普通空格、制表符、
//     换行、回车、全角空格（U+3000）、不换行空格（U+00A0）等任意混用仍算
//     没有原因；扫描只判定不修剪，含实际文字的原因连同其前后、中间空白
//     原样保留；
//   - 只校验状态值确为字符串 "rejected" 的申请。有效（approved）免修原本
//     就可以没有 reason，已撤销（revoked）免修沿用既有读取与核对行为，
//     二者都不增加原因限制；状态写成 null、number 等非字符串情形由结构体
//     解码与随后的 loadData 按类型/非法状态拒绝，本扫描不替它们改口。
//
// 报错推迟到该免修对象完整读完时（objectEnd）发出，这样无论 id、student
// 出现在原因字段之前还是之后，错误都能点名学生与免修编号。
func scanRejectedWaiverReasons(r io.Reader) error {
	type waiverState struct {
		studentID string
		waiverID  string

		// status 确为字符串值时记录解码后的文字并置 statusKnown；status
		// 为 null/其他类型时 statusKnown 保持 false（留给解码阶段拒绝）。
		statusKnown bool
		statusValue string

		// reason 字段出现后，其值归为互斥的四类：字符串（reasonString，
		// 文字记在 reasonValue）、JSON null（reasonNull）、其余标量或
		// 对象/数组（reasonNotText）。键一出现先按“非文字”待定，直接的
		// 字符串/标量值回调再把它改成确切类别；对象、数组值不会在免修帧
		// 上触发值回调，于是保持“非文字”，与 number、bool 同一口径拒绝。
		reasonPresent bool
		reasonKey     string
		reasonString  bool
		reasonValue   string
		reasonNull    bool
		reasonNotText bool
	}
	// 每个对象一份状态，随遍历器的 objectStart/objectEnd 成对压退；只有
	// 免修对象会写入其中字段。
	var states []waiverState

	hooks := recordTokenHooks{
		objectStart: func(objKind) {
			states = append(states, waiverState{})
		},
		objectEnd: func(kind objKind) error {
			st := states[len(states)-1]
			states = states[:len(states)-1]
			if kind != objWaiver || !st.statusKnown || st.statusValue != string(WaiverRejected) {
				return nil
			}
			// 免修对象已完整读完，id/student 无论先后都已记录在案。
			switch {
			case !st.reasonPresent:
				return &missingRejectReasonError{
					studentID: st.studentID, waiverID: st.waiverID, problem: reasonAbsent}
			case st.reasonNull:
				return &missingRejectReasonError{
					studentID: st.studentID, waiverID: st.waiverID,
					key: st.reasonKey, problem: reasonNull}
			case !st.reasonString:
				// number、bool 或对象、数组：拒绝原因必须是文字。
				return &missingRejectReasonError{
					studentID: st.studentID, waiverID: st.waiverID,
					key: st.reasonKey, problem: reasonWrongType}
			case strings.TrimSpace(st.reasonValue) == "":
				return &missingRejectReasonError{
					studentID: st.studentID, waiverID: st.waiverID,
					key: st.reasonKey, problem: reasonBlank}
			}
			return nil
		},
		key: func(kind objKind, key string) error {
			if kind != objWaiver {
				return nil
			}
			if canonical, ok := matchRecordField(objWaiver, key); ok && canonical == "reason" {
				st := &states[len(states)-1]
				st.reasonPresent = true
				st.reasonKey = key
				// 先按“非文字”待定；直接的字符串/标量值回调会覆盖它，
				// 对象/数组值不触发值回调，最终仍按非文字拒绝。
				st.reasonNotText = true
			}
			return nil
		},
		stringValue: func(kind objKind, key, value string) error {
			if kind != objWaiver {
				return nil
			}
			st := &states[len(states)-1]
			canonical, ok := matchRecordField(objWaiver, key)
			if !ok {
				return nil
			}
			switch canonical {
			case "id":
				st.waiverID = value
			case "student":
				st.studentID = value
			case "status":
				// 只有字符串值才算“确为某状态”；状态值区分大小写，
				// "Rejected" 等不是合法状态，由解码阶段拒绝。
				st.statusValue = value
				st.statusKnown = true
			case "reason":
				st.reasonString = true
				st.reasonNotText = false
				st.reasonValue = value
			}
			return nil
		},
		scalarValue: func(kind objKind, key string, tok any) error {
			if kind != objWaiver {
				return nil
			}
			canonical, ok := matchRecordField(objWaiver, key)
			if !ok || canonical != "reason" {
				return nil
			}
			// JSON null 的 token 是无类型 nil；number、bool 等其余标量
			// 也不是合法原因文字，二者都要拒绝，只是说明措辞不同。
			st := &states[len(states)-1]
			st.reasonNotText = false
			if tok == nil {
				st.reasonNull = true
			} else {
				st.reasonNotText = true
			}
			return nil
		},
	}
	// 语法问题留给随后的结构体解码报告；本检查只负责发现缺失的拒绝原因。
	return walkFirstRecordValue(r, false, hooks)
}

// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
//   - 字符串中直接写入的字节必须是合法 UTF-8；
//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
//
// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
// 文件，整份判为内容损坏，哪怕问题只出现在一条已拒绝免修的依据里、或在与
// 本次核对无关的课程名称里。
//
// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
//
// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
// 本来就会被读取方拒绝，无需在此重复判定。
func scanStringUnicode(raw []byte) error {
	i := 0
	for i < len(raw) && isJSONSpace(raw[i]) {
		i++
	}
	if i >= len(raw) {
		return nil // 空输入交由后续结构体解码报错
	}
	switch raw[i] {
	case '"':
		// 顶层就是一个字符串：扫描它本身即可。
		_, err := scanJSONString(raw, i)
		return err
	case '{', '[':
	default:
		return nil // 顶层标量（数字、true、false、null）不含字符串
	}
	depth := 0
	for i < len(raw) {
		switch raw[i] {
		case '"':
			j, err := scanJSONString(raw, i)
			if err != nil {
				return err
			}
			i = j
		case '{', '[':
			depth++
			i++
		case '}', ']':
			depth--
			i++
			if depth == 0 {
				// 唯一的顶层值已完整读完，其后内容不在本检查范围。
				return nil
			}
		default:
			i++
		}
	}
	return nil // 未闭合的结构由 JSON 解析报错
}

// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
func scanJSONString(raw []byte, start int) (int, error) {
	i := start + 1
	for i < len(raw) {
		c := raw[i]
		switch {
		case c == '"':
			return i + 1, nil
		case c == '\\':
			if i+1 >= len(raw) {
				return len(raw), nil
			}
			if raw[i+1] != 'u' {
				i += 2 // 其他转义的合法性由 JSON 解析器校验
				continue
			}
			v, ok := hex4(raw, i+2)
			if !ok {
				i += 2 // 非法 \u 转义形式由 JSON 解析器报错
				continue
			}
			switch {
			case isHighSurrogate(v):
				// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
				if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
					if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
						i += 12
						continue
					}
				}
				return 0, fmt.Errorf(
					`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
			case isLowSurrogate(v):
				return 0, fmt.Errorf(
					`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
			default:
				i += 6
			}
		case c < utf8.RuneSelf:
			i++
		default:
			// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
			// 是合法文字：只有解码失败（size 为 1）才拒绝。
			r, size := utf8.DecodeRune(raw[i:])
			if r == utf8.RuneError && size == 1 {
				return 0, fmt.Errorf(
					"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
			}
			i += size
		}
	}
	return i, nil // 未闭合的字符串由 JSON 解析器报错
}

func isJSONSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }

// hex4 把 b[i:i+4] 读作四位十六进制数。
func hex4(b []byte, i int) (rune, bool) {
	if i+4 > len(b) {
		return 0, false
	}
	var v rune
	for k := 0; k < 4; k++ {
		c := b[i+k]
		var d byte
		switch {
		case '0' <= c && c <= '9':
			d = c - '0'
		case 'a' <= c && c <= 'f':
			d = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			d = c - 'A' + 10
		default:
			return 0, false
		}
		v = v*16 + rune(d)
	}
	return v, true
}

