package credit

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestProbeResultStatusBadByte(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "records.json")

	s := NewStore()
	mustCourse(t, s, "c1", "数学", 4)
	mustStudent(t, s, "s1")
	mustReq(t, s, "s1", "r1", "c1")
	mustEnroll(t, s, "s1", "r1", "2024春", "e1")
	if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
		t.Fatal(err)
	}
	// 已拒绝免修（目标要求另有通过修读、免修不提供学分）。
	if w, _, err := s.ApplyWaiver("s1", "r2", "wbad", "旧依据"); err != nil ||
		w.Status != WaiverRejected {
		t.Fatalf("构造被拒绝免修失败：%+v %v", w, err)
	}
	if err := s.Save(path); err != nil {
		t.Fatal(err)
	}
	before, _ := os.ReadFile(path)

	// 场景1：已有修读结果被设成“较长文字中夹非法字节”。
	e := s.Enrollment("s1", "e1")
	e.Result = Result("通过" + badByte + "passed" + badByte + "结束")
	err := s.Save(path)
	if err == nil || !strings.Contains(err.Error(), "无法原样保存") ||
		!strings.Contains(err.Error(), "修读") || !strings.Contains(err.Error(), "结果") ||
		!strings.Contains(err.Error(), "e1") || !strings.Contains(err.Error(), path) {
		t.Fatalf("修读结果非法应拒绝并点名文件/类别/编号/字段：%v", err)
	}
	after, _ := os.ReadFile(path)
	if string(after) != string(before) {
		t.Fatal("原文件必须逐字节保持")
	}
	if !strings.Contains(string(e.Result), badByte) || strings.Contains(string(e.Result), "�") {
		t.Fatalf("内存中的原始结果不得被修补：% x", []byte(e.Result))
	}
	if s.Waiver("s1", "wbad") == nil {
		t.Fatal("历史条目不能被删除")
	}
	if l, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp")); len(l) != 0 {
		t.Fatalf("不得残留临时文件：%v", l)
	}

	// 恢复结果，再污染已拒绝免修的状态（该要求另有通过修读、免修不提供学分）。
	e.Result = Passed
	w := s.Waiver("s1", "wbad")
	w.Status = WaiverStatus("状态：rejected" + badByte + "尾部")
	err = s.Save(path)
	if err == nil || !strings.Contains(err.Error(), "免修") ||
		!strings.Contains(err.Error(), "状态") || !strings.Contains(err.Error(), "wbad") {
		t.Fatalf("已拒绝免修状态非法应拒绝整次保存并点名免修/状态/编号：%v", err)
	}
	after2, _ := os.ReadFile(path)
	if string(after2) != string(before) {
		t.Fatal("原文件必须逐字节保持（第二次拒绝）")
	}
	if !strings.Contains(string(w.Status), badByte) {
		t.Fatalf("内存中的原始状态不得被修补：% x", []byte(string(w.Status)))
	}
}
